(7748630, 1279453, 67258, '<td valign="top">How cool is that!</td>', 'How cool is that!', '2023-06-08 09:53:57.000000', NULL, 1),
(7748633, 1280080, 67258, '<td valign="top">I think for this challenge I would have preferred a tighter crop removing the left hand section up to the window edge.  The pull of the central and centre left part of your composition is so strong that my eye is drawn away from the door and chair, which is a really interesting part of the frame!</td>', 'I think for this challenge I would have preferred a tighter crop removing the left hand section up to the window edge.  The pull of the central and centre left part of your composition is so strong that my eye is drawn away from the door and chair, which is a really interesting part of the frame!', '2023-06-08 10:11:05.000000', NULL, 1),
(7748634, 1279238, 67258, '<td valign="top">Fascinating, aesthetically pleasing - I don''t need to know what the object is to enjoy the image.</td>', 'Fascinating, aesthetically pleasing - I don''t need to know what the object is to enjoy the image.', '2023-06-08 10:40:53.000000', NULL, 1),
(7748635, 1279787, 67258, '<td valign="top">I love the composition, but I''m really not very keen on the treatment you have given it.  The image looks curiously flat, and lacking in contrast.  The toning and nod to infra-red don''t work for me.  I''d really like to see this one with a different edit.</td>', 'I love the composition, but I''m really not very keen on the treatment you have given it.  The image looks curiously flat, and lacking in contrast.  The toning and nod to infra-red don''t work for me.  I''d really like to see this one with a different edit.', '2023-06-08 10:44:12.000000', NULL, 1),
(7748636, 1279935, 67258, '<td valign="top">i really like this one - good strong mono conversion, lots of drama and tension created by the contrast and by the composition.  Bumping to a 9.</td>', 'i really like this one - good strong mono conversion, lots of drama and tension created by the contrast and by the composition.  Bumping to a 9.', '2023-06-08 10:44:27.000000', NULL, 1),
(7748637, 1280061, 67258, '<td valign="top">What a fab place, and an excellent composition - I would like just a tad more contrast in your mono conversion, but a good entry. Bumping to an 8.</td>', 'What a fab place, and an excellent composition - I would like just a tad more contrast in your mono conversion, but a good entry. Bumping to an 8.', '2023-06-08 10:44:43.000000', NULL, 1),
