(7749232, 1280080, 83313, '<td valign="top">A hobbit, I would presume?</td>', 'A hobbit, I would presume?', '2023-06-11 18:51:28.000000', NULL, 1),
(7749233, 1280055, 83313, '<td valign="top">I like the detail on this, but I think it could use a little more oomph to grab and steer the eye. Would probably make a great contrasty B/W.</td>', 'I like the detail on this, but I think it could use a little more oomph to grab and steer the eye. Would probably make a great contrasty B/W.', '2023-06-11 18:52:51.000000', NULL, 1),
(7749235, 1279753, 83313, '<td valign="top">I have no idea what this is, but I don''t think I need to know to appreciate it. The tag and the wisp of smoke are intriguing though.</td>', 'I have no idea what this is, but I don''t think I need to know to appreciate it. The tag and the wisp of smoke are intriguing though.', '2023-06-11 18:54:51.000000', NULL, 1),
(7749236, 1280107, 83313, '<td valign="top">I like it. I think of these as semi-abstracts. You can tell what it is, but the subject of the image is the textures, shapes and colors. I may have to try something similar with my own house plants.</td>', 'I like it. I think of these as semi-abstracts. You can tell what it is, but the subject of the image is the textures, shapes and colors. I may have to try something similar with my own house plants.', '2023-06-11 18:56:38.000000', NULL, 1),
(7749237, 1279439, 83313, '<td valign="top">Hate to drop a 5 on a drone photo, but I''ll be honest that this isn''t grabbing me in any way. Nothing wrong with it either. I guess that is the definition of a 5, right? Sorry.</td>', 'Hate to drop a 5 on a drone photo, but I''ll be honest that this isn''t grabbing me in any way. Nothing wrong with it either. I guess that is the definition of a 5, right? Sorry.', '2023-06-11 18:58:26.000000', NULL, 1),
